from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class Iprtv6ParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        if self.enb_ent_config['gateway_ipv6']:
            static_ipv6_routes = {
                'destIpv6Addr': '::',
                'destinationIpv6PrefixLength': 0,
                'gatewayIpv6Addr': self.enb_ent_config['gateway_ipv6'],
                'preSrcIpv6Addr': '::',
                'preference': 1
            }
            for subparam_name, subparam_value in static_ipv6_routes.items():
                self.set_struct_parameter('staticIpv6Routes', subparam_name, subparam_value)
